"""Strict wire validation for protocol version 3.

Every rule of PROTOCOL.md "Input" is checked here before any planning work is
done: unique keys at every depth, single JSON object to EOF, no non finite
constants, exact JSON types for integer fields, container depth and every
numeric bound.  Anything else raises Invalid, which the entry point turns into
the single {"error":"invalid"} answer.
"""
import json

MAX_INPUT = 16 * 1024 * 1024
MAX_DEPTH = 64
MAX_EPOCHS = 8
MAX_WINDOWS = 1024
TIME_MAX = 10 ** 12


class Invalid(ValueError):
    pass


def _reject(_name):
    raise Invalid('nonfinite')


def _pairs(items):
    out = {}
    for k, v in items:
        if k in out:
            raise Invalid('duplicate key')
        out[k] = v
    return out


def parse(raw):
    if not isinstance(raw, (bytes, bytearray)):
        raise Invalid('type')
    if len(raw) > MAX_INPUT:
        raise Invalid('size')
    try:
        text = raw.decode('utf-8', 'strict')
    except Exception:
        raise Invalid('utf8')
    try:
        obj = json.loads(text, object_pairs_hook=_pairs, parse_constant=_reject)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')
    return obj


def _depth(o, d):
    t = type(o)
    if t is dict:
        if d > MAX_DEPTH:
            raise Invalid('depth')
        for v in o.values():
            _depth(v, d + 1)
    elif t is list:
        if d > MAX_DEPTH:
            raise Invalid('depth')
        for v in o:
            _depth(v, d + 1)


def _want_dict(o, keys):
    if type(o) is not dict:
        raise Invalid('object expected')
    if set(o) != set(keys):
        raise Invalid('keys')
    return o


def _int(o, lo, hi):
    if type(o) is not int:
        raise Invalid('integer expected')
    if o < lo or o > hi:
        raise Invalid('range')
    return o


def _row(o, n):
    if type(o) is not list or len(o) != n:
        raise Invalid('row')
    return o


def _ints(o, n, lo, hi):
    _row(o, n)
    return [_int(v, lo, hi) for v in o]


def validate(obj):
    _depth(obj, 1)
    _want_dict(obj, ('version', 'cases'))
    if _int(obj['version'], 3, 3) != 3:
        raise Invalid('version')
    cases = obj['cases']
    if type(cases) is not list or len(cases) > MAX_EPOCHS:
        raise Invalid('cases')
    out = []
    total = 0
    for c in cases:
        ep = _case(c)
        total += len(ep['windows'])
        if total > MAX_WINDOWS:
            raise Invalid('window budget')
        out.append(ep)
    return out


def _acyclic(parent):
    n = len(parent)
    state = [0] * n
    for i in range(n):
        if state[i]:
            continue
        walk = []
        idx = set()
        cur = i
        while cur >= 0:
            if state[cur] == 2:
                break
            if state[cur] == 1 or cur in idx:
                raise Invalid('group cycle')
            idx.add(cur)
            walk.append(cur)
            state[cur] = 1
            cur = parent[cur]
        for v in walk:
            state[v] = 2
    return parent


def _case(c):
    _want_dict(c, ('model', 'class_values', 'stats', 'bucket', 'slots',
                   'flows', 'groups', 'windows'))
    model = c['model']
    if type(model) is not str or model not in ('cnn', 'rnn'):
        raise Invalid('model')
    class_values = _ints(c['class_values'], 7, 1, 1000)
    stats = _ints(c['stats'], 3, 1, 10 ** 9)
    bucket = _row(c['bucket'], 2)
    B = _int(bucket[0], 1, 512)
    I = _int(bucket[1], 0, B)
    slots = c['slots']
    if type(slots) is not list or not (1 <= len(slots) <= 256):
        raise Invalid('slots')
    times = []
    caps = []
    refs = []
    prev = None
    for r in slots:
        _row(r, 3)
        t = _int(r[0], 0, TIME_MAX)
        q = _int(r[1], 0, 512)
        rf = _int(r[2], 0, 512)
        if prev is not None and t <= prev:
            raise Invalid('slot order')
        prev = t
        times.append(t)
        caps.append(q)
        refs.append(rf)
    if refs[0] != 0:
        raise Invalid('first refill')
    groups = c['groups']
    if type(groups) is not list or len(groups) > 32:
        raise Invalid('groups')
    gparent = []
    gceil = []
    for r in groups:
        _row(r, 2)
        p = _int(r[0], -1, len(groups) - 1)
        if p >= len(groups):
            raise Invalid('parent')
        cl = _int(r[1], 0, 512)
        gparent.append(p)
        gceil.append(cl)
    for i, p in enumerate(gparent):
        if p == i:
            raise Invalid('self parent')
    _acyclic(gparent)
    flows = c['flows']
    if type(flows) is not list or not (1 <= len(flows) <= 32):
        raise Invalid('flows')
    for r in flows:
        _row(r, 4)
        tg = _int(r[0], 1, 64)
        cl = _int(r[1], tg, 512)
        gp = _int(r[2], -1, len(groups) - 1)
        lb = _int(r[3], 0, 6)
    windows = c['windows']
    if type(windows) is not list or len(windows) > 512:
        raise Invalid('windows')
    nflows = len(flows)
    for r in windows:
        _row(r, 8)
        _int(r[0], 0, nflows - 1)
        rd = _int(r[1], 0, TIME_MAX)
        _int(r[2], rd, TIME_MAX)
        _int(r[3], 1, 65535)
        _int(r[4], 1, 320)
        _int(r[5], 0, 65535)
        _int(r[6], 1, 1000)
        feats = r[7]
        if type(feats) is not list or len(feats) != 9:
            raise Invalid('features')
        for fr in feats:
            _row(fr, 2)
            _int(fr[0], 0, 1500)
            _int(fr[1], 0, 2560)
    return {
        'model': model,
        'class_values': class_values,
        'stats': stats,
        'bucket': (B, I),
        'slots': slots,
        'flows': flows,
        'groups': groups,
        'windows': windows,
    }
PYEOF
